    # Strategy 1: Symmetric x/y-swap with Generalized Doubling
    # Pattern: A = x^a + y^b + y^(k1*b), B = y^d + x^e + x^(k2*e)
    # We iterate over multipliers {2, 3} to capture both doubling and tripling structures.
    # We maintain coprimality preference for 'a' and 'd' (the single terms) to ensure
    # effective mixing, but allow 'b' and 'e' to be more flexible.

    def _gcd(u: int, v: int) -> int:
        while v:
            u, v = v, u % v
        return abs(u)

    # Candidates for single terms (x^a in A, y^d in B) - prefer coprime
    singles_x = [x for x in range(1, ell) if _gcd(x, ell) == 1]
    singles_y = [y for y in range(1, m) if _gcd(y, m) == 1]

    # Candidates for pair bases (y^b in A, x^e in B) - can be anything small/coprime
    # We limit to first half to reduce duplicates via symmetry
    bases_y = [y for y in range(1, m) if _gcd(y, m) == 1]
    bases_x = [x for x in range(1, ell) if _gcd(x, ell) == 1]

    # Pruning for speed if lists are large
    if len(singles_x) > 6: singles_x = singles_x[:6]
    if len(singles_y) > 6: singles_y = singles_y[:6]
    if len(bases_x) > 8: bases_x = bases_x[:8]
    if len(bases_y) > 8: bases_y = bases_y[:8]

    multipliers = [2, 3]

    for a in singles_x:
        for b in bases_y:
            for k1 in multipliers:
                c = (k1 * b) % m
                if c == 0 or c == b: continue
                A = [(a, 0), (0, b), (0, c)]

