    # Strategy 5: Constant-Monomial Codes (High k potential)
    # Pattern: A = 1 + y^a + y^b, B = 1 + x^c + x^d
    #
    # Improvements:
    #  - prioritize "linked" doubling (b=2a, d=2c) and "3x" (b=3a) variants
    #  - include a few known-good y gaps (2,7), (2,10), (1,5) modulo m when possible
    #  - strong coprimality filter on step sizes to favor large orbits
    #
    y_exps = set(range(1, min(m, 12)))
    x_exps = set(range(1, min(ell, 12)))

    # add divisors and a few multiples (but don't explode to all k)
    for k in range(1, m):
        if m % k == 0:
            y_exps.add(k)
            if 2 * k < m:
                y_exps.add(2 * k)
            if 3 * k < m:
                y_exps.add(3 * k)
    for k in range(1, ell):
        if ell % k == 0:
            x_exps.add(k)
            if 2 * k < ell:
                x_exps.add(2 * k)
            if 3 * k < ell:
                x_exps.add(3 * k)

    y_exps = sorted({t % m for t in y_exps if 0 < (t % m) < m})
    x_exps = sorted({t % ell for t in x_exps if 0 < (t % ell) < ell})

    # inject a few "gap pairs" for y and x (when in range)
    gap_pairs_y = [(1, 2), (2, 7), (2, 10), (1, 5), (3, 8)]
    gap_pairs_x = [(1, 2), (2, 4), (3, 6), (5, 10), (4, 8)]

    def _coprime_step(step: int, mod: int) -> bool:
        return step != 0 and _gcd(step, mod) == 1

    # linked (doubling / tripling) families
    for a in y_exps:
        if not _coprime_step(a, m):
            continue
        for mult in (2, 3):
            b = (mult * a) % m
            if b == 0 or b == a:
